"""Write web/src/lib/api.gen.ts from the desk API's OpenAPI schemas. Run: make api-types.

Covers what pydantic emits for the desk's models: objects, arrays, refs, nullable
unions, literals and enums. Builds the app without starting it: no gateway, no orders.
tests/test_api_types.py fails while the committed file is stale.
"""

from __future__ import annotations

import sys
from pathlib import Path
from typing import Any

OUT = Path(__file__).resolve().parents[2] / "web" / "src" / "lib" / "api.gen.ts"

_HEADER = """\
// Generated by backend/scripts/api_types.py from the desk API's OpenAPI schemas.
// Do not edit: change backend/src/mayedge/api/{schemas,responses}.py and run `make api-types`.
"""

_SCALARS = {
    "string": "string",
    "integer": "number",
    "number": "number",
    "boolean": "boolean",
    "null": "null",
}


def _ts(schema: dict[str, Any]) -> str:
    if "$ref" in schema:
        return str(schema["$ref"]).rsplit("/", 1)[-1]
    if "const" in schema:
        return _literal(schema["const"])
    if "enum" in schema:
        return " | ".join(_literal(v) for v in schema["enum"])
    for key in ("anyOf", "oneOf"):
        if key in schema:
            return " | ".join(dict.fromkeys(_ts(s) for s in schema[key]))
    kind = schema.get("type")
    if kind == "array":
        inner = _ts(schema.get("items") or {})
        return f"({inner})[]" if " | " in inner else f"{inner}[]"
    if kind == "object":
        extra = schema.get("additionalProperties")
        if isinstance(extra, dict) and not schema.get("properties"):
            return f"Record<string, {_ts(extra)}>"
        return "Record<string, unknown>"
    if isinstance(kind, str) and kind in _SCALARS:
        return _SCALARS[kind]
    return "unknown"


def _literal(value: object) -> str:
    if isinstance(value, str):
        return '"' + value.replace("\\", "\\\\").replace('"', '\\"') + '"'
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "true" if value else "false"
    return str(value)


def _interface(name: str, schema: dict[str, Any]) -> str:
    required = set(schema.get("required") or [])
    lines = [f"export interface {name} {{"]
    for prop, sub in (schema.get("properties") or {}).items():
        mark = "" if prop in required else "?"
        lines.append(f"  {prop}{mark}: {_ts(sub)};")
    lines.append("}")
    return "\n".join(lines)


def render(document: dict[str, Any]) -> str:
    schemas: dict[str, Any] = document.get("components", {}).get("schemas", {})
    blocks = [
        _interface(name, schema)
        for name, schema in sorted(schemas.items())
        if schema.get("type") == "object" and name not in ("HTTPValidationError", "ValidationError")
    ]
    return _HEADER + "\n" + "\n\n".join(blocks) + "\n"


def generated() -> str:
    from mayedge.api.app import create_app

    return render(create_app().openapi())


if __name__ == "__main__":
    OUT.write_text(generated())
    sys.stdout.write(f"wrote {OUT}\n")
